def find_ways(n):
    # Initialize a 2D list to store the number of ways to generate sequences of length n
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Base cases
    for i in range(1, n + 1):
        dp[i][1] = 1  # There's one way to generate a sequence of length 1 with a single element

    # Fill the dp table
    for i in range(2, n + 1):
        for j in range(2, i + 1):
            dp[i][j] = dp[i - 1][j] + dp[i - 1][j - 1]

    # The number of ways to generate a sequence of length n is the sum of ways to generate sequences of length n-1 and n-2
    return dp[n][n]

