def permutation_coefficient(n, k):
    # Base case: if k is 0 or n is 0, the permutation coefficient is 1
    if k == 0 or n == 0:
        return 1
    # Recursive case: calculate the permutation coefficient
    else:
        # Calculate the factorial of n
        n_fact = 1
        for i in range(1, n + 1):
            n_fact *= i
        # Calculate the factorial of k
        k_fact = 1
        for i in range(1, k + 1):
            k_fact *= i
        # Calculate the permutation coefficient
        return n_fact // (k_fact * (n - k))

